#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Puts Loopboard live: Neon production and preview databases, the Vercel project,
# Google sign-in, and each environment's variables (issue #30).
# Run from the repo root on Node 24: ./scripts/setup-deploy.sh
#
# Production values (connection string, Google secret, auth secret) live only in
# Vercel's Production environment: they're held in memory for this run, handed
# over on the clipboard one at a time, and never written to disk. The local .env
# gets only the dev/preview Google client, local auth settings, OWNER_EMAIL, and
# PREVIEW_DATABASE_URL (so re-runs remember it).

PROD_DOMAIN=""; PROD_DATABASE_URL=""; PROD_GOOGLE_CLIENT_ID=""; PROD_GOOGLE_CLIENT_SECRET=""
OWNER_EMAIL=""; PREVIEW_DATABASE_URL=""; GOOGLE_CLIENT_ID=""; GOOGLE_CLIENT_SECRET=""

POSTGRES_URL='^postgres(ql)?://[^[:space:]]+$'
GOOGLE_CLIENT='\.apps\.googleusercontent\.com$'
NONBLANK='^[^[:space:]]+$'
VERCEL_DOMAIN='^[a-z0-9-]+\.vercel\.app$'

# copy_value VALUE puts VALUE on the clipboard; fails when there's no clipboard tool.
copy_value() {
  if   command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  elif command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy  >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  else return 1; fi
}

# has_clipboard: whether copy_value has a tool to use.
has_clipboard() {
  command -v clip.exe >/dev/null 2>&1 || command -v pbcopy >/dev/null 2>&1 \
    || command -v wl-copy >/dev/null 2>&1 || command -v xclip >/dev/null 2>&1
}

# skip_if_done "what": whether this stage's setup already happened on an earlier run.
skip_if_done() { confirm "Already did this ($1) on an earlier run? Skip it"; }

# ask_until KEY "Prompt" REGEX [secret] asks until the answer matches REGEX.
ask_until() {
  local key="$1" prompt="$2" regex="$3" secret="${4:-}"
  while true; do
    if [[ -n "$secret" ]]; then ask_secret "$key" "$prompt"; else ask "$key" "$prompt"; fi
    [[ "${!key}" =~ $regex ]] && return 0
    warn "That doesn't look right; try again."
  done
}

# require KEY "Prompt" REGEX [secret] asks only if this run hasn't captured KEY yet.
# Production values are never saved, so a re-run that skipped their stages asks here.
require() { [[ -n "${!1}" ]] || ask_until "$@"; }

# vercel_var NAME VALUE ENVIRONMENT TYPE walks one variable through Vercel's
# Environment Variables form, with the value on the clipboard rather than the screen.
vercel_var() {
  local name="$1" value="$2" environment="$3" type="$4"
  printf '\n  %s%s%s  %s(%s only · %s)%s\n' "$BOLD" "$name" "$RESET" "$DIM" "$environment" "$type" "$RESET"
  step "Add New → Name: $name"
  if copy_value "$value"; then
    step "Value: paste it (Ctrl-V); it's on your clipboard."
  elif [[ "$type" == "Secret" ]]; then
    if confirm "No clipboard tool. Show the value on screen so you can copy it"; then say "$value"; fi
  else
    step "Value: $value"
  fi
  step "Environments: tick only $environment. Type: $type. Save."
  pause "Saved $name? Press Enter"
}

run_wizard() {

TOTAL_STAGES=13

banner "Loopboard: production and preview deploys"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
if [[ ! -f package.json ]] || ! grep -q '"vercel-build"' package.json; then
  warn "Run this from the repo root (no vercel-build script here)."; exit 1
fi
node_major=$(node --version 2>/dev/null | sed -E 's/^v([0-9]+).*/\1/' || true)
if [[ "$node_major" != "24" ]]; then
  warn "Needs Node 24 on PATH (found: ${node_major:-none}). Try: fnm use 24"; exit 1
fi
command -v openssl >/dev/null 2>&1 || { warn "Needs openssl to generate secrets."; exit 1; }
has_clipboard || warn "No clipboard tool (clip.exe, pbcopy, wl-copy, xclip): secret values will be shown on request instead."
if [[ ! -d node_modules ]]; then
  if confirm "Dependencies aren't installed. Run npm ci now"; then npm ci; else warn "Install dependencies first."; exit 1; fi
fi
git fetch -q origin main 2>/dev/null || true
if ! git show origin/main:package.json 2>/dev/null | grep -q '"node": "24.x"'; then
  warn "origin/main doesn't pin engines.node to 24.x yet."
  note "Vercel defaults to Node 26 and engines overrides the dashboard setting:"
  note "merge the PR that adds this wizard first, or production may build on Node 26."
  pause "Press Enter to carry on anyway"
fi
say "You'll need a Neon account, a Vercel Hobby account linked to GitHub, and a"
say "Google account for Google Cloud Console."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Neon: production database"
say "Production gets its own Neon project, in a Neon account of its own: sign up"
say "on Neon directly, not through Vercel's Neon integration."
open_url "https://console.neon.tech/signup"
step "Sign up or sign in on Neon."
step "Create project → name: loopboard-production · default Postgres version ·"
step "  region: AWS US East 1 (N. Virginia), next to Vercel's default functions region."
step "Click Connect on the project dashboard ('Connect to your branch')."
step "Turn OFF 'Connection pooling' to get the direct string (no -pooler in its host)."
step "Copy the connection string (postgresql://...)."
warn "This string goes only into Vercel Production, nowhere else."
ask_until PROD_DATABASE_URL "Paste the production connection string (hidden):" "$POSTGRES_URL" secret
note "Held in memory for stage 10; never written to disk."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Neon: preview database"
say "A second Neon project for previews: its own host and role, so nothing holding"
say "the preview credential can reach production."
open_url "https://console.neon.tech/app/projects"
step "New project → name: loopboard-preview · same region."
step "Connect → turn OFF 'Connection pooling' → copy the connection string."
ask_until PREVIEW_DATABASE_URL "Paste the preview connection string (hidden):" "$POSTGRES_URL" secret
if [[ "$PREVIEW_DATABASE_URL" == "$PROD_DATABASE_URL" ]]; then
  warn "That's the production string. Use the loopboard-preview project's."; exit 1
fi
write_env PREVIEW_DATABASE_URL "$PREVIEW_DATABASE_URL"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Preview database: migrations and synthetic seed"
say "Applies the committed migrations to the preview database, then loads the"
say "synthetic seed (invented people at example.com). Preview builds re-apply"
say "migrations on every deploy; the seed is loaded once and skips if present."
if confirm "Migrate and seed the PREVIEW database now"; then
  DATABASE_URL="$PREVIEW_DATABASE_URL" npm run --silent db:migrate
  PREVIEW_DATABASE_URL="$PREVIEW_DATABASE_URL" npx -y tsx@4 scripts/seed-preview.ts
else
  SKIPPED+=("Preview DB: DATABASE_URL=<preview> npm run db:migrate, then PREVIEW_DATABASE_URL=<preview> npx tsx scripts/seed-preview.ts")
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Vercel: create the project"
if ! skip_if_done "Vercel project import"; then
  open_url "https://vercel.com/new"
  step "Import Git Repository → ecarlste/get-a-job-dude (connect GitHub if asked)."
  step "Project Name: loopboard, or a neutral variant if it's taken (nothing naming"
  step "  you or job hunting). It becomes <name>.vercel.app."
  step "Framework: Next.js (auto-detected). Add NO environment variables here."
  step "Deploy. This first build fails at db:migrate (no DATABASE_URL yet): expected."
  step "  Stage 12 redeploys it."
fi
step "Find the production domain: project → Settings → Domains."
ask_until PROD_DOMAIN "Production domain (e.g. loopboard.vercel.app):" "$VERCEL_DOMAIN"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Vercel: Node 24 and deployment protection"
open_url "https://vercel.com/dashboard"
step "Project → Settings → Build and Deployment → Node.js Version: 24.x → Save."
step "Settings → Deployment Protection → Vercel Authentication: on,"
step "  scope 'Standard Protection' (every deployment except production domains)."
note "Previews sit behind a Vercel sign-in; production stays public."
pause "Both set? Press Enter"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Google: project and consent screen"
if ! skip_if_done "Google Cloud project and consent screen"; then
  open_url "https://console.cloud.google.com/projectcreate"
  step "Create a project named loopboard, then select it."
  pause "Project created and selected? Press Enter"
  open_url "https://console.cloud.google.com/auth/overview"
  step "Google Auth Platform → Get started:"
  step "  App name: Loopboard · support email: yours · Audience: External ·"
  step "  contact email: yours → agree → Create."
  step "Audience → Publish app. It asks only openid/email/profile, so no verification"
  step "  should be needed. If Google insists, stay in Testing: basic-scope sign-in"
  step "  works for any Google account even then."
  pause "Consent screen done? Press Enter"
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Google: production OAuth client"
say "Production gets its own client, so its secret lives only in Vercel Production."
open_url "https://console.cloud.google.com/auth/clients"
step "Create client → Application type: Web application → name: Loopboard production."
step "Authorized JavaScript origins: https://$PROD_DOMAIN"
step "Authorized redirect URIs:      https://$PROD_DOMAIN/api/auth/callback/google"
step "Create. The secret is shown ONCE: copy it now, and don't download the JSON."
note "Redirect URI changes can take a few minutes to apply at Google."
ask_until PROD_GOOGLE_CLIENT_ID "Paste the client ID:" "$GOOGLE_CLIENT"
ask_until PROD_GOOGLE_CLIENT_SECRET "Paste the client secret (hidden):" "$NONBLANK" secret
note "Held in memory for stage 10; never written to disk."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Google: dev and preview OAuth client"
say "A second client for local dev and Vercel Preview. Google allows no wildcard"
say "redirect URIs and every preview URL is unique, so Google sign-in on previews"
say "needs a code change (a follow-up issue). For now this client registers localhost."
open_url "https://console.cloud.google.com/auth/clients"
step "Create client → Web application → name: Loopboard dev and preview."
step "Authorized JavaScript origins: http://localhost:3000"
step "Authorized redirect URIs:      http://localhost:3000/api/auth/callback/google"
step "Create, then copy the ID and the secret (shown once)."
ask_until GOOGLE_CLIENT_ID "Paste the client ID:" "$GOOGLE_CLIENT"
ask_until GOOGLE_CLIENT_SECRET "Paste the client secret (hidden):" "$NONBLANK" secret
if [[ "$GOOGLE_CLIENT_ID" == "$PROD_GOOGLE_CLIENT_ID" ]]; then
  warn "That's the production client. Use the dev and preview one."; exit 1
fi
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
write_env BETTER_AUTH_URL "http://localhost:3000"
local_auth_secret=$(_existing BETTER_AUTH_SECRET || true)
write_env BETTER_AUTH_SECRET "${local_auth_secret:-$(openssl rand -base64 32)}"
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Vercel: Production environment variables"
require PROD_DOMAIN "Production domain (e.g. loopboard.vercel.app):" "$VERCEL_DOMAIN"
require PROD_DATABASE_URL "Production connection string (hidden):" "$POSTGRES_URL" secret
require PROD_GOOGLE_CLIENT_ID "Production Google client ID:" "$GOOGLE_CLIENT"
require PROD_GOOGLE_CLIENT_SECRET "Production Google client secret (hidden):" "$NONBLANK" secret
ask_until OWNER_EMAIL "Owner email (the Google account that becomes the Owner):" '^[^@[:space:]]+@[^@[:space:]]+$'
write_env OWNER_EMAIL "$OWNER_EMAIL"
open_url "https://vercel.com/dashboard"
step "Project → Settings → Environment Variables. Six variables, Production only."
vercel_var DATABASE_URL "$PROD_DATABASE_URL" Production Secret
vercel_var BETTER_AUTH_SECRET "$(openssl rand -base64 32)" Production Secret
vercel_var BETTER_AUTH_URL "https://$PROD_DOMAIN" Production Config
vercel_var GOOGLE_CLIENT_ID "$PROD_GOOGLE_CLIENT_ID" Production Config
vercel_var GOOGLE_CLIENT_SECRET "$PROD_GOOGLE_CLIENT_SECRET" Production Secret
vercel_var OWNER_EMAIL "$OWNER_EMAIL" Production Secret

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Vercel: Preview environment variables"
require PREVIEW_DATABASE_URL "Preview connection string (hidden):" "$POSTGRES_URL" secret
require GOOGLE_CLIENT_ID "Dev and preview Google client ID:" "$GOOGLE_CLIENT"
require GOOGLE_CLIENT_SECRET "Dev and preview Google client secret (hidden):" "$NONBLANK" secret
say "Five variables, Preview only (all branches). BETTER_AUTH_URL stays unset: each"
say "preview URL differs, and Better Auth infers it from the request. OWNER_EMAIL is"
say "the synthetic seed's Owner, so nothing real reaches previews."
vercel_var DATABASE_URL "$PREVIEW_DATABASE_URL" Preview Secret
vercel_var BETTER_AUTH_SECRET "$(openssl rand -base64 32)" Preview Secret
vercel_var GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID" Preview Config
vercel_var GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET" Preview Secret
vercel_var OWNER_EMAIL "avery@example.com" Preview Config
if copy_value " "; then note "Clipboard cleared."; fi
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Production: deploy and sign in"
open_url "https://vercel.com/dashboard"
step "Project → Deployments → latest Production deployment → … → Redeploy."
step "  From now on, merging to main does this."
step "In the build log, db:migrate applies the migrations before next build."
pause "Build finished? Press Enter to open the site"
open_url "https://$PROD_DOMAIN"
step "The tab title reads 'Loopboard', and nothing on the page names you."
step "Sign in with Google as $OWNER_EMAIL: you land on the main view as the Owner."
if ! confirm "Production deployed, migrated, and you're signed in as the Owner"; then
  SKIPPED+=("Production sign-in: check the build log and Production env vars (redirect_uri_mismatch means stage 8's URI)")
fi

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Preview: check it's protected"
say "Every PR now gets a preview deploy on the preview database."
open_url "https://vercel.com/dashboard"
step "Project → Deployments → copy the URL of a Preview deployment (open a PR first"
step "  if there's none)."
step "Open it in a private window: you should hit Vercel's sign-in wall."
step "Signed in to Vercel, it shows the app's sign-in page. Google sign-in on previews"
step "  waits on the follow-up issue."
if ! confirm "Preview is behind Vercel Authentication"; then
  SKIPPED+=("Preview protection: Settings → Deployment Protection → Vercel Authentication, Standard Protection")
fi

PROD_DATABASE_URL=""; PROD_GOOGLE_CLIENT_SECRET=""
finish
}

run_wizard "$@"; exit

